def descriptions(language):
 result=HELP[language].copy()
 for p in ['betterTab.highlight.self','betterTab.highlight.friends','betterTab.highlight.others']:
  result[p+'.color']={'en_us':'Row background ARGB color, including alpha.','zh_cn':'行背景的 ARGB 颜色，包含透明度。','zh_tw':'列背景的 ARGB 色彩，包含透明度。'}[language]
 for p in ['betterTab.highlight.others.filter','betterTab.playerHider.filter']:
  result[p+'.filterBy']={'en_us':'Test the optional display name, the raw profile name, or both.','zh_cn':'选择匹配可选显示名、原始玩家名，或两者。','zh_tw':'選擇比對可選顯示名稱、原始玩家名稱，或兩者。'}[language]
  result[p+'.names']={'en_us':'Java regular expressions matched against the whole selected name. Empty list matches nobody.','zh_cn':'对整个选定名称匹配的 Java 正则表达式；空列表不匹配任何人。','zh_tw':'對整個選定名稱比對的 Java 規則運算式；空清單不符合任何人。'}[language]
 source=json.loads((ROOT/f'upstream/LiquidBounce/src/main/resources/resources/liquidbounce/lang/{language}.json').read_text(encoding='utf8'))
 result={f'liquidbounce.module.{k}.description':v for k,v in result.items()}
 for m in ['mobOwners','combineMobs','betterTab']:
  key=f'liquidbounce.module.{m}.description';result[key]=source[key]
 return result
def update(language,target):
 data=json.loads(target.read_text(encoding='utf8'));data['labels'].update(LABELS[language]);data['descriptions'].update(descriptions(language))
 if language=='zh_cn':data['englishDescriptions'].update(descriptions('en_us'))
 target.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--directory',required=True);a=p.parse_args()
 for language in ['zh_cn','zh_tw']:update(language,ROOT/a.directory/f'display_{language}.json')
